#include <stdio.h>

int main(void) {
    int code;
    scanf("%d", &code);
    int first = code / 1000;
    int second = code / 100 % 10;
    int third = code / 10 % 10;
    int last = code % 10;
    if (code < 1000 || code > 9999) {
        printf("DENIED: length\n");
    } else if (first == last) {
        printf("DENIED: mirror\n");
    } else if (second + third <= 9) {
        printf("DENIED: weak\n");
    } else {
        printf("GRANTED\n");
    }
    return 0;
}
